def gen(rng):
    from fractions import Fraction

    def nonsingular(A):
        n = len(A)
        M = [[Fraction(x) for x in row] for row in A]
        for c in range(n):
            piv = None
            for r in range(c, n):
                if M[r][c] != 0:
                    piv = r
                    break
            if piv is None:
                return False
            M[c], M[piv] = M[piv], M[c]
            for r in range(c + 1, n):
                if M[r][c] != 0:
                    f = M[r][c] / M[c][c]
                    M[r] = [x - f * y for x, y in zip(M[r], M[c])]
        return True

    def fmt(A, B):
        n = len(A)
        m = len(B[0])
        C = [[sum(A[i][k] * B[k][j] for k in range(n)) for j in range(m)] for i in range(n)]
        lines = ['%d %d' % (n, m)]
        lines += [' '.join(map(str, r)) for r in A]
        lines += [' '.join(map(str, r)) for r in C]
        return '\n'.join(lines)

    def randB(n, m, br):
        return [[rng.randint(-br, br) for _ in range(m)] for _ in range(n)]

    def randA(n, ar, zero_p=0.0):
        while True:
            A = [[0 if rng.random() < zero_p else rng.randint(-ar, ar) for _ in range(n)] for _ in range(n)]
            if nonsingular(A):
                return A

    tests = [
        fmt([[-3]], [[2, 0, -7]]),
        fmt([[1]], [[5]]),
        fmt([[2, 1], [1, 1]], [[1, 2], [3, 4]]),
        fmt([[0, 2], [3, 0]], [[4], [-5]]),
        fmt([[1, 0, 0], [0, 1, 0], [0, 0, 1]], [[1, 2], [3, 4], [5, 6]]),
        fmt([[0, 0, 1], [1, 0, 0], [0, 1, 0]], [[7, -8], [9, 10], [-11, 12]]),
        fmt([[1, 2, 3], [0, 1, 4], [0, 0, 1]], [[1], [-1], [1]]),
        fmt([[5, 5], [5, 4]], [[0, 0], [0, 0]]),
    ]
    for n in (1, 2, 3, 4, 5):
        for _ in range(3):
            m = rng.randint(1, 5)
            tests.append(fmt(randA(n, 9, rng.choice([0.0, 0.3])), randB(n, m, 20)))
    tests.append(fmt(randA(30, 9), randB(30, 30, 50)))
    tests.append(fmt(randA(30, 9, 0.5), randB(30, 30, 50)))
    A = [[0 if j < i - 0 else rng.randint(1, 9) * rng.choice([-1, 1]) if j == i else rng.randint(-9, 9) for j in range(30)] for i in range(30)]
    tests.append(fmt(A, randB(30, 30, 50)))
    A = randA(30, 9)
    A[0] = [0] + A[0][1:]
    while not nonsingular(A):
        A = randA(30, 9)
        A[0] = [0] + A[0][1:]
    tests.append(fmt(A, randB(30, 1, 50)))
    tests.append(fmt(randA(30, 9), randB(30, 30, 50)))
    return tests
